#!/usr/bin/env python3
"""Regenerates a monitoring-enabled copy of config/default.yaml - same
model, mcp_servers, courses, subagents (all capabilities), only the
monitoring block and metrics bind host are overridden. Single source of
truth stays default.yaml; this script is what keeps the copy from
drifting out of sync with it.
"""
from __future__ import annotations

import argparse
from pathlib import Path

import yaml

GENERATED_HEADER = (
    "# GENERATED by scripts/generate_monitoring_config.py from config/default.yaml.\n"
    "# Do not edit directly - changes here are overwritten on the next run.\n"
)


def generate(source: Path, dest: Path) -> None:
    data = yaml.safe_load(source.read_text(encoding="utf-8")) or {}

    monitoring = data.get("monitoring") or {}
    monitoring["enabled"] = True
    metrics = monitoring.get("metrics") or {}
    metrics["enabled"] = True
    metrics["host"] = "0.0.0.0"
    metrics.setdefault("port", 8000)
    # Longer than config/prometheus/prometheus.yml's scrape_interval, so the
    # last few seconds of a session are still scraped after the agent exits.
    metrics.setdefault("linger_seconds", 3)
    monitoring["metrics"] = metrics
    monitoring.setdefault("jsonl", {
        "enabled": True,
        "path": ".agent_monitoring/events.jsonl",
        "queue_capacity": 1024,
        "max_record_bytes": 8192,
        "max_file_bytes": 10485760,
        "backup_count": 3,
    })
    monitoring.setdefault("shutdown_timeout_seconds", 2)
    data["monitoring"] = monitoring

    dest.write_text(GENERATED_HEADER + yaml.dump(data, sort_keys=False), encoding="utf-8")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source", type=Path, required=True)
    parser.add_argument("--dest", type=Path, required=True)
    args = parser.parse_args()
    generate(args.source, args.dest)
    print(f"Regenerated {args.dest} from {args.source}")
